/** Rule joins use the method abstraction for completed mark-demand deliveries. */
class RunMethodLocalServices(core: BlockRunState) : MethodLocalServices {
    private var owner: BlockRunState? = core
    private var conjunctionStore: ConjunctionStore? = if (core.forward) ConjunctionStore(core.ap, core.context.shared.n2Statistics) else null
    private var predicateStore: RulePredicateStore? =
        if (core.forward) RulePredicateStore(core.ap, core.context.shared.formStatistics) else null
    private var originConjunctionStore: Run1OriginConjunctionStore? =
        if (core.forward && core.config.run1) Run1OriginConjunctionStore(core.ap) else null
    private var originPredicateStore: Run1OriginPredicateStore? =
        if (core.forward && core.config.run1) Run1OriginPredicateStore(core.ap, core.context.shared.formStatistics) else null
    // FULL condition evidence belongs to one semantic operation point. E6
    // call-summary joins keep the separate actor-wide conjunctionStore above.
    private val conditionConjunctions = HashMap<NormalRuleSite, ConjunctionStore>()
    private val conditionPredicates = HashMap<NormalRuleSite, RulePredicateStore>()
    private val conditionOriginConjunctions = HashMap<NormalRuleSite, Run1OriginConjunctionStore>()
    private val conditionOriginPredicates = HashMap<NormalRuleSite, Run1OriginPredicateStore>()
    override val conjunctions: ConjunctionStore? get() = conjunctionStore
    private var triggered: HashSet<Pair<CommonInst, Any>>? = HashSet()
    override val hasPendingRequests: Boolean get() = owner?.abstraction?.hasPending == true

    private fun activeCore(): BlockRunState =
        checkNotNull(owner) { "The local services were frozen" }.also { it.ap.cancellation.checkpoint() }

    private fun predicatesAt(rule: NormalRuleDescriptor, at: OperationInput): RulePredicateStore {
        val core = activeCore()
        return if (core.mode.markMode != MarkMode.FULL) checkNotNull(predicateStore)
        else conditionPredicates.getOrPut(NormalRuleContributors.stableSite(rule, at.site)) {
            RulePredicateStore(core.ap, core.context.shared.formStatistics)
        }
    }

    private fun conjunctionsAt(rule: NormalRuleDescriptor, at: OperationInput): ConjunctionStore {
        val core = activeCore()
        return if (core.mode.markMode != MarkMode.FULL) checkNotNull(conjunctionStore)
        else conditionConjunctions.getOrPut(NormalRuleContributors.stableSite(rule, at.site)) {
            ConjunctionStore(core.ap, core.context.shared.n2Statistics)
        }
    }

    private fun originPredicatesAt(rule: NormalRuleDescriptor, at: OperationInput): Run1OriginPredicateStore {
        val core = activeCore()
        return if (core.mode.markMode != MarkMode.FULL) checkNotNull(originPredicateStore)
        else conditionOriginPredicates.getOrPut(NormalRuleContributors.stableSite(rule, at.site)) {
            Run1OriginPredicateStore(core.ap, core.context.shared.formStatistics)
        }
    }

    private fun originConjunctionsAt(rule: NormalRuleDescriptor, at: OperationInput): Run1OriginConjunctionStore {
        val core = activeCore()
        return if (core.mode.markMode != MarkMode.FULL) checkNotNull(originConjunctionStore)
        else conditionOriginConjunctions.getOrPut(NormalRuleContributors.stableSite(rule, at.site)) {
            Run1OriginConjunctionStore(core.ap)
        }
    }

    /** Only a current accepted leaf activates earlier NORMAL conditional
     * evidence. Ready cached bindings use this invocation's ordinary callback. */
    private fun <B> acceptedLeaf(rule: NormalRuleDescriptor, at: OperationInput, leaf: Int,
                               input: ConjunctionStore.Input,
                               add: (Int, ConjunctionStore.Input, (B) -> Unit) -> Unit,
                               cache: Boolean = true,
                               emit: (B) -> Unit) {
        val core = activeCore()
        if (!cache) { add(leaf, input, emit); return }
        val ready = ArrayList<B>()
        if (!core.config.run1) core.normalRuleContributors.restoreOnce(rule, at.site) { saved ->
            add(saved.leaf, saved.input) { ready += it }
        }
        core.normalRuleContributors.keep(rule, at.site, leaf, input)
        for (binding in ready) emit(binding)
        add(leaf, input, emit)
    }

    override fun addMarkRequest(premise: InitialAp, mark: TaintMark) {
        val core = activeCore()
        check(core.config.run1) { "Requests exist only in run 1" }
        checkNotNull(core.abstraction).requireMark(premise, mark)
        if (hasPendingRequests) core.requestWork()
    }

    override fun addMarkRequests(premise: InitialAp, marks: RequestMarkSet) {
        val core = activeCore()
        check(core.config.run1) { "Requests exist only in run 1" }
        checkNotNull(core.abstraction).requireMarks(premise, marks)
        if (hasPendingRequests) core.requestWork()
    }

    override fun flushRequests(quantum: Int): Boolean {
        val core = activeCore()
        require(quantum > 0) { "The request-work quantum must be positive" }
        return core.abstraction?.flush(quantum) ?: true
    }

    override fun conjunction(edge: ConjunctiveEdge, premise: PremiseKey, facts: Facts, node: CommonInst,
                             sink: (PremiseKey, Facts) -> Unit) = conjunctionAt(edge, premise, facts, node,
        OperationInput(ResumeSite.StatementInput(activeCore().operation(node)), premise, facts), sink)

    override fun conjunctionAt(edge: ConjunctiveEdge, premise: PremiseKey, facts: Facts, node: CommonInst,
                               at: OperationInput, sink: (PremiseKey, Facts) -> Unit) {
        val core = activeCore()
        if (!RuntimeDataDomain.packet(premise, facts) || !RuntimeDataDomain.base(edge.target.base)) return
        check(core.forward) { "A backward form has independent conjunction branches" }
        val rule = NormalRuleDescriptor.legacyConjunction(edge)
        val store = conjunctionsAt(rule, at)
        for ((index, literal) in edge.literals.withIndex()) {
            core.ap.cancellation.checkpoint()
            if (literal.fact.base != facts.base) continue
            when (val checked = core.ops.checkMark(facts, literal, core.mode, core.unchangedStaticInitial(premise))) {
                MarkCheck.None -> Unit
                is MarkCheck.Request -> core.needGroups(at, checked.mark)
                is MarkCheck.Holds -> {
                    val input = ConjunctionStore.Input(premise, checked.facts.layer, checked.facts)
                    if (core.config.run1) {
                        core.normalRuleContributors.keep(rule, at.site, index, input)
                        val targets = HashMap<Layer, Facts>()
                        val assigned = runtimeAtom(core, (edge.target.mark as? MarkSlot.Concrete)?.mark)
                        val triggering = runtimeAtom(core, (literal.fact.mark as? MarkSlot.Concrete)?.mark)
                        originConjunctionsAt(rule, at).addProtectedOrigins(edge, node, edge.literals.size, index, input, assigned, triggering) { initial, layer, nonSubsumable ->
                            val result = targets.getOrPut(layer) { core.ops.targetTree(edge.target, layer, core.mode) }
                            sink(initial, core.forceRun1Layer(initial, protectTarget(result, nonSubsumable)))
                        }
                        continue
                    }
                    acceptedLeaf<ConjunctionStore.Combination>(rule, at, index, input,
                        add = { leaf, accepted, emit ->
                            for (combination in store.add(edge, node, edge.literals.size, leaf, accepted)) emit(combination)
                        }) { combination ->
                        core.ap.cancellation.checkpoint()
                        val result = core.ops.targetTree(edge.target, combination.layer, core.mode)
                        val protected = ruleProtection(core, combination.inputs, combination.premise,
                            runtimeAtom(core, (edge.target.mark as? MarkSlot.Concrete)?.mark))
                        sink(combination.premise, core.forceRun1Layer(combination.premise, protectTarget(result, protected)))
                        core.ap.cancellation.checkpoint()
                    }
                }
            }
        }
    }

    override fun sourcePredicate(source: SourceRuleOccurrence, premise: PremiseKey, facts: Facts, node: CommonInst,
                                 statementEdge: Boolean, sink: (PremiseKey, Facts) -> Unit) =
        sourcePredicateAt(source, premise, facts, node, statementEdge,
            OperationInput(ResumeSite.StatementInput(activeCore().operation(node)), premise, facts), sink)

    override fun sourcePredicateAt(source: SourceRuleOccurrence, premise: PremiseKey, facts: Facts, node: CommonInst,
                                   statementEdge: Boolean, at: OperationInput, sink: (PremiseKey, Facts) -> Unit) =
        sourcePredicateActionsAt(source, premise, facts, node, statementEdge, at) { pr, result, _ -> sink(pr, result) }

    override fun sourcePredicateActionsAt(source: SourceRuleOccurrence, premise: PremiseKey, facts: Facts, node: CommonInst,
                                          statementEdge: Boolean, at: OperationInput,
                                          sink: (PremiseKey, Facts, ActionId?) -> Unit) {
        val core = activeCore()
        if (!RuntimeDataDomain.packet(premise, facts)) return
        if (source.actions.isEmpty()) return
        val predicate = source.predicate
        fun transfer(pattern: Pattern, multi: Boolean) {
            for (action in source.actions) {
                core.ap.cancellation.checkpoint()
                val edge = source.transfer(pattern, action, multi)
                if (!RuntimeDataDomain.producer(edge) || edge.edge.from.base != facts.base) continue
                if (core.config.seededSources && !core.config.seeds.allowsSource(core.key, node, edge.forward, action.id)) continue
                core.ops.applyEdge(facts, premise, edge.edge, statementEdge, core.mode,
                    core.collectAfterRun1Policy(at) { _, result ->
                        core.sourceHits?.add(core.key, node, edge.forward, action.id)
                        sink(premise, result, action.id)
                    }, may = edge.may, ruleAssignment = true)
            }
        }
        if (source.backward) {
            check(!core.forward)
            for (leaf in predicate.leaves.indices) {
                core.ap.cancellation.checkpoint()
                if (predicate.isUnary(leaf)) transfer(predicate.leaves[leaf], multi = false)
                if (predicate.isMulti(leaf)) transfer(predicate.leaves[leaf], multi = true)
            }
            return
        }
        check(core.forward)
        val rule = NormalRuleDescriptor.predicate(source.id)
        fun multiLeaf(selected: RulePredicate, leaf: Int, pattern: Pattern, allowSingle: Boolean) {
            when (val checked = core.ops.checkMark(facts, pattern, core.mode, core.unchangedStaticInitial(premise))) {
                MarkCheck.None -> Unit
                is MarkCheck.Request -> core.needGroups(at, checked.mark)
                is MarkCheck.Holds -> if (core.config.run1) {
                    val input = ConjunctionStore.Input(premise, checked.facts.layer, checked.facts)
                    core.normalRuleContributors.keep(rule, at.site, leaf, input)
                    originPredicatesAt(rule, at).add(source.id, node, selected, leaf, input) { cube ->
                        if (allowSingle || cube.leaves.size >= 2) for (action in source.actions) {
                            core.ap.cancellation.checkpoint()
                            if (!RuntimeDataDomain.base(action.target.base)) continue
                            if (core.config.seededSources && cube.leaves.none { index ->
                                core.config.seeds.allowsSource(core.key, node,
                                    source.transfer(selected.leaves[index], action, multi = true).forward, action.id)
                            }) continue
                            val results = HashMap<Layer, Facts>()
                            val assigned = runtimeAtom(core, (action.target.mark as? MarkSlot.Concrete)?.mark)
                            cube.emitProtectedOrigins(action.id, assigned) { initial, layer, nonSubsumable ->
                                val result = results.getOrPut(layer) { core.ops.targetTree(action.target, layer, core.mode) }
                                sink(initial, core.forceRun1Layer(initial, protectTarget(result, nonSubsumable)), action.id)
                            }
                        }
                    }
                } else acceptedLeaf<RulePredicateStore.Combination>(rule, at, leaf,
                    ConjunctionStore.Input(premise, checked.facts.layer, checked.facts),
                    add = { index, input, emit -> predicatesAt(rule, at).add(source.id, node, selected, index, input, emit) }) { combination ->
                    // GROUP folding can leave one accepted leaf in an original MULTI transfer.
                    if (allowSingle || combination.leaves.size >= 2) for (action in source.actions) {
                        core.ap.cancellation.checkpoint()
                        if (!RuntimeDataDomain.base(action.target.base)) continue
                        if (core.config.seededSources && combination.leaves.none { index ->
                            core.config.seeds.allowsSource(core.key, node,
                                source.transfer(selected.leaves[index], action, multi = true).forward, action.id)
                        }) continue
                        val result = core.ops.targetTree(action.target, combination.layer, core.mode)
                        val protected = ruleProtection(core, combination.inputs, combination.premise,
                            runtimeAtom(core, (action.target.mark as? MarkSlot.Concrete)?.mark))
                        sink(combination.premise, core.forceRun1Layer(combination.premise, protectTarget(result, protected)), action.id)
                    }
                }
            }
        }
        if (core.config.run1 && source.groupTransfers) {
            for (unary in source.unaryTransfers) {
                core.ap.cancellation.checkpoint()
                matchingLeaves(core, unary.predicate, facts) { _, _ ->
                    // Use the declared anchor and original Facts, never the checked AP piece.
                    transfer(unary.anchor, multi = false)
                }
            }
            source.multiPredicate?.let { multi ->
                matchingLeaves(core, multi, facts) { leaf, pattern -> multiLeaf(multi, leaf, pattern, allowSingle = true) }
            }
            return
        }
        matchingLeaves(core, predicate, facts) { leaf, pattern ->
            core.ap.cancellation.checkpoint()
            if (predicate.isUnary(leaf)) transfer(pattern, multi = false)
            if (predicate.isMulti(leaf)) multiLeaf(predicate, leaf, pattern, allowSingle = false)
        }
    }

    private fun runtimeAtom(core: BlockRunState, atom: TaintMark?): TaintMark? =
        atom?.let { core.ap.marks.runtimeAtom(it, core.mode.markMode) }

    /** All accepted contributors remain in the exact ND premise. */
    private fun ruleProtection(core: BlockRunState, inputs: List<ConjunctionStore.Input>,
                               premise: PremiseKey, assigned: TaintMark?): Boolean {
        if (assigned == null) return false
        val triggers = ArrayList<TaintMark>()
        for (input in inputs) {
            val facts = input.facts as? TaintTree ?: continue
            if (facts.nonSubsumable != null) return true
            val leaves = core.ap.taintAlg.foldAll(facts.root, core.ap.cancellation)
            for (id in (leaves.exact + leaves.any).ids) triggers += core.ap.marks.runtimeAtom(TaintMark(id), core.mode.markMode)
        }
        if (assigned in triggers) return true
        return triggers.any { it != assigned } && premise.members.any {
            runtimeAtom(core, (it.mark as? MarkSlot.Concrete)?.mark) == assigned
        }
    }

    private fun protectTarget(result: Facts, nonSubsumable: Boolean): Facts =
        if (nonSubsumable && result is TaintTree) result.withProtection(result.root) else result

    override fun checkSinks(premise: PremiseKey, node: CommonInst, facts: Facts, sinks: List<SinkRule>): Triggers {
        return checkSinksAt(premise, node, facts, sinks,
            OperationInput(ResumeSite.StatementInput(activeCore().operation(node)), premise, facts))
    }

    override fun checkSinksAt(premise: PremiseKey, node: CommonInst, facts: Facts, sinks: List<SinkRule>, at: OperationInput): Triggers {
        val core = activeCore()
        if (!RuntimeDataDomain.packet(premise, facts)) return Triggers(emptyList(), emptyList())
        if (!core.forward || sinks.isEmpty()) return Triggers.NONE
        val fired = ArrayList<Pair<SinkRule, Layer>>()
        val parts = ArrayList<Facts>()
        for (sink in sinks) {
            core.ap.cancellation.checkpoint()
            val predicate = sink.predicate
            if (predicate != null && !predicate.isTrue) {
                val rule = NormalRuleDescriptor.predicate(checkNotNull(sink.occurrenceId))
                matchingLeaves(core, predicate, facts) { index, literal ->
                    core.ap.cancellation.checkpoint()
                    when (val checked = core.ops.checkMark(facts, literal, core.mode, core.unchangedStaticInitial(premise))) {
                        MarkCheck.None -> Unit
                        is MarkCheck.Request -> core.needGroups(at, checked.mark)
                        is MarkCheck.Holds -> {
                            parts += checked.facts
                            acceptedLeaf<RulePredicateStore.CompletePredicateBinding>(rule, at, index,
                                ConjunctionStore.Input(premise, checked.facts.layer, checked.facts),
                                add = { leaf, input, emit -> predicatesAt(rule, at).addBinding(
                                    checkNotNull(sink.occurrenceId), node, predicate, leaf, input, emit) },
                                cache = predicate.isMulti(index)) { combination ->
                                val edges = combination.inputs.map {
                                    SinkEdge(it.premise, it.layer, checkNotNull(it.facts))
                                }
                                witness(core, sink, node, edges, combination.proof)
                                fired += sink to combination.layer
                            }
                        }
                    }
                }
                continue
            }
            for ((index, literal) in sink.patterns.withIndex()) {
                core.ap.cancellation.checkpoint()
                when (val checked = core.ops.checkMark(facts, literal, core.mode, core.unchangedStaticInitial(premise))) {
                    MarkCheck.None -> Unit
                    is MarkCheck.Request -> core.needGroups(at, checked.mark)
                    is MarkCheck.Holds -> {
                        parts += checked.facts
                        if (!sink.conjunctive) {
                            witness(core, sink, node, listOf(SinkEdge(premise, checked.facts.layer, checked.facts)))
                            fired += sink to checked.facts.layer
                        } else {
                            val rule = NormalRuleDescriptor.legacySink(sink)
                            acceptedLeaf<ConjunctionStore.CompleteBinding>(rule, at, index,
                                ConjunctionStore.Input(premise, checked.facts.layer, checked.facts),
                                add = { leaf, input, emit ->
                                    for (combination in conjunctionsAt(rule, at).addBinding(sink.joinKey, node,
                                        sink.patterns.size, leaf, input)) emit(combination)
                                }) { combination ->
                                core.ap.cancellation.checkpoint()
                                val edges = combination.inputs.map { input ->
                                    core.ap.cancellation.checkpoint()
                                    SinkEdge(input.premise, input.layer, checkNotNull(input.facts))
                                }
                                witness(core, sink, node, edges)
                                fired += sink to combination.layer
                            }
                        }
                    }
                }
            }
        }
        return Triggers(fired.distinct(), parts)
    }

    private fun matchingLeaves(core: BlockRunState, predicate: RulePredicate, facts: Facts,
                               visit: (Int, Pattern) -> Unit) {
        when (facts) {
            is FlowTree -> predicate.matchingLeaves(facts.base, mark = null, visit)
            is Reach -> predicate.matchingLeaves(facts.base, TaintMark.ZERO, visit)
            is TaintTree -> {
                val leaves = core.ap.taintAlg.foldAll(facts.root, core.ap.cancellation)
                val marks = leaves.exact + leaves.any
                for (mark in marks.data) {
                    core.ap.cancellation.checkpoint()
                    predicate.matchingLeaves(facts.base, TaintMark(mark), visit)
                }
            }
        }
    }

    private fun witness(core: BlockRunState, sink: SinkRule, node: CommonInst, edges: List<SinkEdge>, proof: ProofKey? = null) {
        core.ap.cancellation.checkpoint()
        if (edges.any { !RuntimeDataDomain.packet(it.premise, it.facts) }) return
        val origins = edges.map { it.premise }.distinct()
        val cubeLayer = if (edges.any { it.layer == Layer.DEMAND }) Layer.DEMAND else Layer.NORMAL
        if (core.forward) {
            val id = core.context.shared.reportCatalog.internReached(
                SinkKey(core.key.method, node, sink.rule.id), sink.rule, core.key)
            core.reachedSinkReportIds += id
        }
        var demandSeedCaptured = false
        fun emitArm(premise: PremiseKey, layer: Layer) {
            val target = if (layer == Layer.NORMAL) {
                Target.NormalTarget(core.context.shared.reportCatalog.intern(
                    SinkKey(core.key.method, node, sink.rule.id), sink.rule, core.key))
            } else {
                if (!demandSeedCaptured) {
                    val projected = sink.predicate == null && sink.patterns.any {
                        (it.fact.mark as? MarkSlot.Concrete)?.mark?.let(core.ap.marks::isGroup) == true
                    }
                    core.sinkSeeds.addAll(if (projected)
                        org.opentaint.dataflow.bidi.driver.fullSinkSeedsFor(core.context.shared, sink, core.key, node)
                    else org.opentaint.dataflow.bidi.driver.sinkSeedsFor(sink, core.key, node))
                    demandSeedCaptured = true
                }
                Target.DemandTarget
            }
            core.emitTarget(premise, target)
        }
        if (core.config.run1) {
            val nonzero = origins.filterNot { it.isZero }
            for (origin in nonzero.ifEmpty { listOf(core.ap.zero) }) {
                val complete = origins.all { it.isZero || it == origin }
                emitArm(origin, if (complete) cubeLayer else Layer.DEMAND)
            }
        } else {
            var original: PremiseKey = core.ap.zero
            for (origin in origins) original = core.ap.union(original, origin)
            emitArm(original, cubeLayer)
        }
    }

    override fun fireSinkSeeds(node: CommonInst, emit: (Facts) -> Unit) {
        val core = activeCore()
        for (seed in core.config.seeds.at(core.key, node)) {
            core.ap.cancellation.checkpoint()
            if (seed is Seed.Sink) seedFact(core, seed.requirement, emit)
            if (seed is Seed.PredicateSink) {
                fun visit(sinks: List<SinkRule>) {
                    val sink = sinks.singleOrNull { it.occurrenceId == seed.occurrence }
                        ?: error("A predicate seed must resolve to its frozen rule occurrence")
                    for (requirement in sink.seedPatterns()) seedFact(core, requirement, emit)
                }
                val call = core.context.callAt(node)
                if (call != null) core.forms.withCall(core.key, node, call) { visit(it.sinks) }
                else core.forms.withStartRules(core.key, node) { visit(it.sinks) }
            }
        }
    }

    override fun fireTriggerSeeds(node: CommonInst, sink: SinkRule, emit: (Facts) -> Unit) {
        val core = activeCore()
        if (!checkNotNull(triggered).add(node to sink.joinKey)) return
        for (literal in sink.seedPatterns()) {
            core.ap.cancellation.checkpoint()
            core.countTriggerSeed()
            seedFact(core, literal, emit)
        }
    }

    private fun seedFact(core: BlockRunState, requirement: Pattern, emit: (Facts) -> Unit) {
        if (!RuntimeDataDomain.base(requirement.fact.base)) return
        core.ap.cancellation.checkpoint()
        core.cut(Cut.SEED, core.ap.zero, core.ops.targetTree(requirement.fact, Layer.NORMAL)) { _, facts ->
            if (core.config.index == 2) {
                // A seed starts at its check, before any caller-input query gate.
                // Validate the bounded value; a deeper named field is lawful before this cut.
                for (leaf in core.ops.leaves(facts)) validateRun2StaticFullInput(core.ap, leaf, core.config.fieldLimit)
            }
            emit(facts)
            core.ap.cancellation.checkpoint()
        }
    }

    override fun freeze() {
        conditionConjunctions.clear()
        conditionPredicates.clear()
        conditionOriginConjunctions.clear()
        conditionOriginPredicates.clear()
        conjunctionStore = null
        predicateStore = null
        originConjunctionStore = null
        originPredicateStore = null
        triggered = null
        owner = null
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.*

/** Only immutable invocation state is retained, never a cached full call plan. */
data class CallResumeState(val callerLayer: Layer, val identityCandidate: Boolean? = null,
                           val pendingDemotion: Boolean = false)

data class OperationInput(val site: ResumeSite, val premise: PremiseKey, val facts: Facts,
                          val callState: CallResumeState? = null)

/** Actor-owned resume directory. Service replies name these rows; they never carry callbacks. */
internal class Run1PointResume(private val core: BlockRunState) {
    private data class PointKey(val site: ResumeSite, val initial: InitialAp, val base: AccessPathBase,
                                val tail: Tail, val fieldExclusion: ExclusionSet, val layer: Layer,
                                val state: CallResumeState?)
    private val pointKeys = HashMap<PointKey, Long>()
    private class PendingFlowImages(private var root: FlowNode) {
        fun addAll(incoming: FlowNode, ap: ApManager) {
            root = FlowAlgebra.mergeAdd(root, incoming, ap.cancellation)
        }
        fun snapshotRoot(): FlowNode = root
    }
    private class PointRow(val id: Long, val key: PointKey) {
        val pending = HashMap<TaintMark, PendingFlowImages>()
    }
    private data class DetachedAnswer(val group: TaintMark, val images: FlowNode)
    private val points = HashMap<Long, PointRow>()
    private data class ReadKey(val site: ResumeSite, val operation: StaticOperation)
    private val readKeys = HashMap<ReadKey, Long>()
    private val reads = HashMap<Long, Pair<OperationInput, StaticOperation>>()
    private data class WriterKey(val premise: PremiseKey, val output: Pattern, val layer: Layer)
    private val writerKeys = HashMap<WriterKey, Long>()
    private val writers = HashMap<Long, WriterKey>()
    private class DirectRow(val key: ReadKey, val payload: OperationInput, var waiting: MarkSet)
    private val direct = HashMap<Long, DirectRow>()
    private val directKeys = HashMap<ReadKey, Long>()
    private class WriterInput(val writer: WriterKey, var waiting: MarkSet)
    private val writerInputs = HashMap<Long, WriterInput>()
    private class ConditionalJoin(val writer: WriterKey) {
        val inputs = arrayOfNulls<RegionGroups>(writer.premise.size)
    }
    private data class JoinInput(val join: Long, val member: Int)
    private val conditionalKeys = HashMap<WriterKey, Long>()
    private val conditional = HashMap<Long, ConditionalJoin>()
    private val joinInputs = HashMap<Long, JoinInput>()
    private sealed interface CallResultKey {
        data class Ap(val output: Pattern, val layer: Layer, val protected: Boolean) : CallResultKey
        data class Terminal(val target: Target) : CallResultKey
    }
    private data class CallKey(val callee: MethodKey, val ref: org.opentaint.dataflow.bidi.store.CallerRef,
                               val linkLayer: Layer, val premise: PremiseKey, val result: CallResultKey, val member: Int, val inputClass: GroupKey)
    private class CallContinuation(val key: CallKey, var part: Subscription, var result: StaticCallResult,
                                   val member: Int) { var waiting = MarkSet.EMPTY }
    private val callKeys = HashMap<CallKey, Long>()
    private val calls = HashMap<Long, CallContinuation>()

    fun callInterest(part: Subscription, result: StaticCallResult, member: Int) {
        if (!RuntimeDataDomain.packet(part.ref.premise, part.added) || !RuntimeDataDomain.premise(result.premise)) return
        val initial = result.premise.member(member)
        val atom = (initial.mark as? MarkSlot.Concrete)?.mark ?: return
        val statistics = core.context.shared.n2Statistics
        val pieces = when (result) {
            is StaticCallResult.Ap -> {
                val pub = result.publication
                if (!RuntimeDataDomain.packet(pub.premise, pub.conclusion)) return
                core.ops.leaves(pub.conclusion).map { leaf ->
                    val plain = core.ap.factsOf(leaf.fact, leaf.exclusion, pub.layer)
                    val conclusion = if (plain is TaintTree && pub.conclusion is TaintTree)
                        plain.withProtection(pub.conclusion.nonSubsumable) else plain
                    CallResultKey.Ap(leaf, pub.layer, conclusion is TaintTree && conclusion.nonSubsumable != null) to StaticCallResult.Ap(pub.copy(conclusion = conclusion))
                }.toList()
            }
            is StaticCallResult.Terminal -> listOf(CallResultKey.Terminal(result.summary.target) to result)
        }
        for ((resultKey, piece) in pieces) {
            statistics?.staticGroupCallOffered()
            val key = CallKey(part.callee, part.ref, part.linkLayer, result.premise, resultKey, member, part.added.groupKey)
            val id = callKeys.getOrPut(key) {
                (core.nextStaticTicket()).also { calls[it] = CallContinuation(key, part, piece, member) }
            }
            val row = calls.getValue(id)
            // AP equality retains the current per-leaf key and protection refresh.
            val previous = row.result
            if (previous is StaticCallResult.Ap && piece is StaticCallResult.Ap)
                row.result = StaticCallResult.Ap(previous.publication.copy(conclusion =
                    core.ap.mergeAddDelta(previous.publication.conclusion, piece.publication.conclusion).first))
            row.part = row.part.copy(added = core.ap.mergeAddDelta(row.part.added, part.added).first)
            val fresh = MarkSet.of(core.ap.marks.runtimeAtom(atom, core.mode.markMode)) - row.waiting
            if (fresh.isEmpty) continue
            statistics?.staticGroupCallFallbackAdmitted()
            row.waiting += fresh
            core.staticBatch.interests += StaticInterest(core.key, id, initial.toPattern(), fresh)
        }
        core.requestWork()
    }

    fun reached(summary: StatementSummary, at: OperationInput) {
        if (!RuntimeDataDomain.packet(at.premise, at.facts)) return
        if (at.facts !is Reach || !at.premise.isZero) return
        for (operation in summary.staticOperations) {
            if (core.config.disableRun1Statics && when (operation) {
                    is StaticOperation.Read -> true
                    is StaticOperation.Write -> core.dropsStaticField(operation.target.fact)
                    is StaticOperation.MarkInput -> operation.position.fact.path.size != 1 ||
                        (operation.position.fact.tail != Tail.EXACT && !operation.includeBase)
                }) continue
            val key = ReadKey(at.site, operation)
            val id = readKeys.getOrPut(key) {
                (core.nextStaticTicket()).also { reads[it] = at to operation }
            }
            when (operation) {
                is StaticOperation.Read -> core.staticBatch.reads += StaticReadRegistration(core.key, id,
                    Pattern(operation.transfer.from, operation.transfer.exclusion))
                is StaticOperation.MarkInput -> {
                    val mark = (operation.position.fact.mark as? MarkSlot.Concrete)?.mark ?: continue
                    val groups = MarkSet.of(core.ap.marks.runtimeAtom(mark, core.mode.markMode))
                    if (operation.position.fact.path.size == 1) {
                        val exact = operation.position.fact.tail == Tail.EXACT
                        // A wildcard is a field-query descriptor, never a class
                        // FLOW initial. Its empty-suffix branch is an exact
                        // global marker; BELOW cleaners omit that branch.
                        if (!exact && !core.config.disableRun1Statics)
                            core.staticBatch.reads += StaticReadRegistration(core.key, id, operation.position)
                        if (exact || operation.includeBase) {
                            val directId = directKeys.getOrPut(key) {
                                (core.nextStaticTicket()).also { direct[it] = DirectRow(key, at, MarkSet.EMPTY) }
                            }
                            val row = direct.getValue(directId)
                            val fresh = groups - row.waiting
                            if (!fresh.isEmpty) {
                                row.waiting += fresh
                                val point = operation.position.copy(fact = operation.position.fact.copy(tail = Tail.EXACT),
                                    exclusion = ExclusionSet.Empty)
                                core.staticBatch.interests += StaticInterest(core.key, directId, point, fresh)
                            }
                        }
                    } else core.staticBatch.reads += StaticReadRegistration(core.key, id, operation.position)
                }
                is StaticOperation.Write -> Unit
            }
        }
        // A late call-summary suffix can reach this operation outside this
        // state's workLocal call. Its final post-S output can be a duplicate,
        // so output admission alone does not reserve work for these effects.
        if (!core.staticBatch.isEmpty) core.requestWork()
    }

    fun request(at: OperationInput, groups: MarkSet) {
        if (!RuntimeDataDomain.packet(at.premise, at.facts)) return
        val original = at.premise as? InitialAp ?: return
        val flow = at.facts as? FlowTree ?: return
        if (original.base != STATIC || original.mark !is MarkSlot.Star) return
        if (groups.isEmpty) return
        val key = PointKey(at.site, original, flow.base, flow.tail, flow.exclusion, flow.layer, at.callState)
        val id = pointKeys.getOrPut(key) {
            (core.nextStaticTicket()).also { points[it] = PointRow(it, key) }
        }
        val row = points.getValue(id)
        var subscribe = MarkSet.EMPTY
        groups.forEach { group ->
            core.ap.cancellation.checkpoint()
            val images = row.pending[group]
            if (images == null) {
                row.pending[group] = PendingFlowImages(flow.root)
                subscribe += group
            } else images.addAll(flow.root, core.ap)
        }
        if (!subscribe.isEmpty) {
            core.staticBatch.interests += StaticInterest(core.key, id, original.toPattern(), subscribe)
        }
        core.requestWork()
    }

    /** Only an executed local producer reaches this boundary. Its bounded
     * scalar relation belongs to the writer, independently of summary deltas. */
    fun localWrite(premise: PremiseKey, value: Facts) {
        if (!RuntimeDataDomain.packet(premise, value)) return
        check(value.base == STATIC)
        // A completed local write already has its permitted concrete input.
        // Supply the actual bounded output here, independently of outgoing exit
        // rules or summary publication. FLOW writers remain registered below.
        if (value is TaintTree) core.staticBatch.supplies += core.staticSlices(value)
        for (leaf in core.ops.leaves(value)) {
            if (leaf.fact.path.size < 2) continue // exact class markers have no FLOW writer
            val region = Run1StaticService.region(leaf)
            core.staticBatch.writes += region
            if (value !is FlowTree) continue
            check(premise is InitialAp && !premise.isZero && premise.mark is MarkSlot.Star)
            val key = WriterKey(premise, leaf, value.layer)
            if (key in writerKeys) continue
            val id = core.nextStaticTicket()
            writerKeys[key] = id
            writers[id] = key
            if (premise.base == STATIC)
                core.staticBatch.writers += StaticWriterRegistration(core.key, id, premise, region)
            else core.staticBatch.flowWriters += StaticFlowWriter(core.key, id, region)
        }
        core.requestWork()
    }

    /** A computed result can supply the pool before its summary is erased.
     * Promotion never admits a new write point or FLOW writer. */
    fun computedGroups(premise: PremiseKey, value: Facts) {
        if (!RuntimeDataDomain.packet(premise, value)) return
        check(value.base == STATIC)
        if (value !is TaintTree) return
        if (core.hasKnownStaticGroupInput(premise)) {
            val initial = premise as InitialAp
            val actual = core.knownStaticInput(initial)
            for (leaf in core.ops.leaves(value)) {
                core.ap.cancellation.checkpoint()
                core.context.shared.n2Statistics?.staticGroupSupplyDirect()
                val scalar = core.ap.factsOf(leaf.fact, leaf.exclusion, value.layer)
                core.composeStaticSummaryWithActualInput(initial, scalar, actual) { value ->
                    core.staticBatch.supplies += core.staticSlices(value)
                }
            }
        } else if (!premise.isZero && (0 until premise.size).all { premise.member(it).base == STATIC }) {
            for (leaf in core.ops.leaves(value)) {
                core.context.shared.n2Statistics?.staticGroupJoinFallback()
                val key = WriterKey(premise, leaf, value.layer)
                if (key in conditionalKeys) continue
                // A fixed-group conditional is a pending complete binding, not a
                // permanent summary archive or a service-side Cartesian join.
                // Its immutable scalar survives erasure of the method row.
                val joinId = core.nextStaticTicket()
                conditionalKeys[key] = joinId
                conditional[joinId] = ConditionalJoin(key)
                repeat(premise.size) { member ->
                    val initial = premise.member(member)
                    val atom = (initial.mark as MarkSlot.Concrete).mark
                    val inputId = core.nextStaticTicket()
                    joinInputs[inputId] = JoinInput(joinId, member)
                    core.staticBatch.interests += StaticInterest(core.key, inputId, initial.toPattern(),
                        MarkSet.of(core.ap.marks.runtimeAtom(atom, core.mode.markMode)))
                }
            }
        }
        if (premise.isZero)
            core.staticBatch.supplies += core.staticSlices(value)
        core.requestWork()
    }

    fun onEffect(effect: StaticOwnerEffect) {
        when (effect) {
            is StaticOwnerEffect.ReadReady -> {
                val (at, operation) = checkNotNull(reads[effect.id]) { "Unknown static read reply" }
                val position = effect.region.fact.path
                if (position.size < 2) return // class-point MarkInput uses the direct group path
                val initial = core.ap.initial(Pattern(PathFact(STATIC, position.take(2), Tail.STAR, MarkSlot.STAR), ExclusionSet.Empty))
                val input = core.ap.factsOf(effect.region.fact.copy(mark = MarkSlot.STAR,
                    tail = if (effect.region.fact.tail == Tail.EXACT || effect.region.fact.tail == Tail.ANY_TAINT) Tail.STAR else effect.region.fact.tail),
                    ExclusionSet.Empty, Layer.DEMAND)
                core.installPoint(initial, input, at.site, at.callState)
            }
            is StaticOwnerEffect.PointReady -> {
                calls[effect.id]?.let { call ->
                    call.waiting -= effect.supply.groups
                    if (call.waiting.isEmpty) { callKeys.remove(call.key); calls.remove(effect.id) }
                    core.staticCallSupply(call.part, call.result, call.member, effect.supply)
                    return
                }
                writerInputs[effect.id]?.let { input ->
                    input.waiting -= effect.supply.groups
                    if (input.waiting.isEmpty) writerInputs.remove(effect.id)
                    publishMatched(input.writer, listOf(effect.supply))
                    core.requestWork()
                    return
                }
                joinInputs.remove(effect.id)?.let { input ->
                    val join = conditional.getValue(input.join)
                    join.inputs[input.member] = effect.supply
                    if (join.inputs.all { it != null }) {
                        conditional.remove(input.join)
                        check(conditionalKeys.remove(join.writer) == input.join)
                        publishMatched(join.writer, join.inputs.map { checkNotNull(it) })
                    }
                    core.requestWork()
                    return
                }
                val directRow = direct[effect.id]
                if (directRow != null) {
                    val at = directRow.payload
                    directRow.waiting -= effect.supply.groups
                    if (directRow.waiting.isEmpty) { directKeys.remove(directRow.key); direct.remove(effect.id) }
                    val actual = core.staticFacts(effect.supply)
                    for (leaf in core.ops.leaves(actual)) {
                        val premise = concreteInitial(leaf)
                        core.installPoint(premise, core.ops.startFact(premise, core.mode), at.site, at.callState)
                    }
                    return
                }
                answerPackedPoint(effect)
            }
            is StaticOwnerEffect.WriterInterest -> {
                val writer = checkNotNull(writers[effect.id]) { "Unknown static writer interest" }
                val original = writer.premise as? InitialAp ?: return
                check(!original.isZero && original.mark is MarkSlot.Star && writer.output.fact.mark is MarkSlot.Star)
                if (original.base == STATIC) {
                    val inputId = core.nextStaticTicket()
                    writerInputs[inputId] = WriterInput(writer, effect.groups)
                    core.staticBatch.interests += StaticInterest(core.key, inputId, original.toPattern(), effect.groups)
                } else {
                    for (atom in effect.groups.ids)
                        core.addMarkRequest(original, TaintMark(atom))
                }
            }
        }
        core.requestWork()
    }

    private fun answerPackedPoint(effect: StaticOwnerEffect.PointReady) {
        val row = checkNotNull(points[effect.id]) { "Unknown static point reply" }
        effect.supply.groups.forEach { group -> check(row.pending.containsKey(group)) }
        val detached = ArrayList<DetachedAnswer>()
        effect.supply.groups.forEach { group ->
            detached += DetachedAnswer(group, checkNotNull(row.pending.remove(group)).snapshotRoot())
        }
        // Detach every supplied group before any callback. Later requests must
        // subscribe again; an immutable detached root cannot acquire new images.
        if (row.pending.isEmpty()) {
            check(pointKeys.remove(row.key) == row.id)
            check(points.remove(row.id) === row)
        }
        for (answer in detached) {
            core.ap.cancellation.checkpoint()
            materializeScalarImages(row.key, answer.images,
                RegionGroups(effect.supply.region, MarkSet.of(answer.group)))
        }
    }

    private fun materializeScalarImages(key: PointKey, images: FlowNode, supply: RegionGroups) {
        val actual = core.staticFacts(supply)
        for (leaf in core.ops.leaves(actual)) {
            core.ap.cancellation.checkpoint()
            val premise = concreteInitial(leaf)
            materializeStaticFlowImages(core.ops, core.mode, key.initial, premise, images,
                key.base, key.tail, key.fieldExclusion, key.layer) { value ->
                core.installPoint(premise, value, key.site, key.state)
            }
        }
    }

    private fun publishMatched(writer: WriterKey, inputs: List<RegionGroups>) {
        // Both FLOW writers and unanswered fixed-mark input joins own the
        // admitted bounded scalar; neither borrows an erased method summary.
        val current = core.ap.factsOf(writer.output.fact, writer.output.exclusion, writer.layer)
        core.composeStaticSummary(writer.premise, current, inputs) { value ->
            core.staticBatch.supplies += core.staticSlices(value)
        }
    }

    private fun concreteInitial(leaf: Pattern): InitialAp = concreteStaticResumeInitial(core.ap, leaf)

    fun clear() { pointKeys.clear(); points.clear(); readKeys.clear(); reads.clear(); writerKeys.clear(); writers.clear(); direct.clear(); directKeys.clear(); callKeys.clear(); calls.clear(); writerInputs.clear(); conditionalKeys.clear(); conditional.clear(); joinInputs.clear() }
}

